ASSETS_SHA256 = 'cde696a9e490608d7d773295547c8e6abe2b90c12cc4e6c74938ebbadf8565b5'
M = None
UI_STATE = '.VOID-Reference-UI.json'
CORE_NAMES = ('PlrSidebar.qml', 'UiSettingsWindow.qml')
PAGE_NAMES = ('UiPerformanceSetting.qml','UiDisplaySetting.qml','UiGraphicsSetting.qml','PlrAboutSetting.qml','PlrAdvancedSetting.qml','PlrAudioSetting.qml','PlrDeviceSetting.qml','PlrGameSetting.qml','PlrGamepadSetting.qml','PlrPreferencesSetting.qml','PlrShortcutsSetting.qml','PlrUserDataSetting.qml')
RESOURCE_NAMES = CORE_NAMES + PAGE_NAMES


def manager():
    global M
    if M is None:
        body = zlib.decompress(base64.b85decode(MANAGER_B85))
        if hashlib.sha256(body).hexdigest() != MANAGER_SHA256: raise RuntimeError('Bundled manager checksum failed.')
        module = types.ModuleType('void_reference_manager')
        module.__file__ = str(Path(sys.executable if getattr(sys, 'frozen', False) else __file__).resolve())
        sys.modules[module.__name__] = module
        exec(compile(body, module.__file__, 'exec'), module.__dict__)
        M = module
    return M


"""Bounded additive native edits. M is the audited standalone manager's lexer."""
import json
import re

ROOT_BLOCK = '''
// VOID REFERENCE UI V3 ROOT BEGIN
property bool pVoidOptimizerActive: false
property bool pVoidOptimizerRequested: false
function fVoidSelectOptimizer() {
    pVoidOptimizerRequested = true
    fChangeSelectedSetting(pCurrentTabIndex)
}
function fVoidSelectNative(index) {
    pVoidOptimizerRequested = false
    fChangeSelectedSetting(index)
}
onPCurrentTabIndexChanged: if (!pVoidOptimizerRequested) pVoidOptimizerActive = false
Component.onDestruction: VoidUiNav.detach(iSettingsWindow)
Shortcut { sequence: "F9"; context: Qt.WindowShortcut; autoRepeat: false; enabled: pVoidOptimizerActive; onActivated: iSettingsWindow.close() }
// VOID REFERENCE UI V3 ROOT END
'''
SWITCH_BLOCK = '''
// VOID REFERENCE UI V3 SWITCH BEGIN
pVoidOptimizerActive = pVoidOptimizerRequested
pVoidOptimizerRequested = false
// VOID REFERENCE UI V3 SWITCH END
'''
COMPLETE_BLOCK = '''
// VOID REFERENCE UI V3 COMPLETE BEGIN
if (pParentWindow === "plr") VoidUiNav.attach(iSettingsWindow)
// VOID REFERENCE UI V3 COMPLETE END
'''
SIDEBAR_BLOCK = '''
// VOID REFERENCE UI V3 SIDEBAR BEGIN
function fOpenVoidReferenceOptimizer() {
    if (!iAppwin.pIsBootComplete) return
    VoidUiNav.request()
    sidebarSettingClicked()
}
Shortcut {
    sequence: "F9"; context: Qt.WindowShortcut; autoRepeat: false
    enabled: iSidebar.visible && iAppwin.pIsBootComplete && uiBackend.pIsShortcutsEnabled
    onActivated: fOpenVoidReferenceOptimizer()
}
Loader {
    objectName: "voidReferenceSidebarSkinLoader"
    source: SIDEBAR_SKIN_URL
    onLoaded: item.host = iSidebar
}
// VOID REFERENCE UI V3 SIDEBAR END
'''
SIDEBAR_ITEM = '''
PlrSidebarElement {
pElementId: "voidOptimizer"
pAsset: "SidebarEcoMode"
pTooltipText: "VOID Optimizer (F9)"
pIsEnable: iAppwin.pIsBootComplete
pVisible: iAppwin.pIsBootComplete
onPVisibleChanged: Qt.callLater(iSidebar.fResetSidebar)
onClicked: fOpenVoidReferenceOptimizer()
},
'''

# The extra action is LAST in the native list, including overflow order.
SIDEBAR_ITEM = ',' + SIDEBAR_ITEM[:-2] + '\n'


def fingerprint(M, source):
    return [(token.kind, token.text) for token in M.lex(source)]


def scan(M, source):
    tokens = M.lex(source)
    return tokens, M.structure(tokens)[0]


def shadow(M, source):
    tokens, pairs = scan(M, source)
    found = []
    for i, token in enumerate(tokens[:-1]):
        if token.text == 'UiShadowContainer' and tokens[i + 1].text == '{':
            end = pairs[i + 1]
            if any([t.text for t in tokens[j:j + 3]] == ['id', ':', 'iSettingsWindowShadowContainer'] for j in range(i + 2, end - 2)):
                found.append((token.start, tokens[end].end))
    M.require(len(found) == 1, 'Unknown Settings shadow container; refusing to guess.')
    return found[0]


def settings_bridge(url):
    return '''UiShadowContainer {
id: iSettingsWindowShadowContainer
anchors.fill: parent
Loader {
    id: voidReferenceShell
    anchors.fill: parent
    Component.onCompleted: setSource(SHELL_URL, {bsiHost:iSettingsWindow,bsiTheme:UiTheme})
    onLoaded: {
        iSelectedSettingControl.parent = item.pageContainer
        item.stylePage(iSelectedSettingControl)
    }
}
Text { anchors.centerIn:parent; visible:voidReferenceShell.status===Loader.Error; color:"white"; text:"VOID Settings assets missing. Restore UI or reinstall the complete pack." }
StackLayout {
    id: iSelectedSettingControl
    anchors.fill:parent
    visible:voidReferenceShell.status===Loader.Ready
    currentIndex:pCurrentTabIndex
    Repeater {
        model:pSettingsItems.pSettingElements
        delegate:Loader {
            Component.onCompleted: {
                var a=model.modelData.pComponentArgs
                a?setSource(model.modelData.pQmlSource,a):setSource(model.modelData.pQmlSource)
            }
            onLoaded: {
                model.modelData.pComponentObj=item
                if(item.fOnQmlLoaded)item.fOnQmlLoaded()
                if(voidReferenceShell.item)voidReferenceShell.item.stylePage(item)
            }
        }
    }
}
}'''.replace('SHELL_URL', json.dumps(url + 'SettingsShell.qml'))


def inject_import(source, url):
    hits = list(re.finditer(r'^import[^\r\n]*[\r\n]+', source, re.M))
    if not hits: raise ValueError('Missing native QML imports.')
    at = hits[-1].end()
    line = 'import ' + json.dumps(url + 'Navigation.js') + ' as VoidUiNav\n'
    return source[:at] + line + source[at:], line


def transform_settings(M, source, baseline, url):
    M.require('VOID REFERENCE UI V3' not in source and 'pVoidOptimizerActive' not in source, 'Existing reference UI needs its matching state/backup; no duplicate injection.')
    a, b = shadow(M, source); c, d = shadow(M, baseline)
    M.require(fingerprint(M, source[:a] + source[b:]) == fingerprint(M, baseline[:c] + baseline[d:]),
              'Installed Settings native callbacks differ from reviewed source. Nothing installed; do not force this build.')
    original_outside = source[:a] + source[b:]
    result = source[:a] + settings_bridge(url) + source[b:]
    tokens, pairs = scan(M, result)
    insertions = []
    for pattern, body in [(['id', ':', 'iSettingsWindow'], ROOT_BLOCK)]:
        hits = [i for i in range(len(tokens) - len(pattern) + 1) if [t.text for t in tokens[i:i+len(pattern)]] == pattern]
        M.require(len(hits) == 1, 'Settings root identity is ambiguous.')
        insertions.append((tokens[hits[0]+2].end, body))
    functions = [i for i in range(len(tokens)-3) if [t.text for t in tokens[i:i+3]] == ['function', 'fSwitchSettingPanel', '(']]
    M.require(len(functions) == 1, 'Missing unique native switch guard.')
    opening = functions[0] + 4
    M.require(tokens[opening].text == '{', 'Unexpected Settings switch arguments.')
    insertions.append((tokens[pairs[opening]].start, SWITCH_BLOCK))
    completed = [i for i in range(len(tokens)-4) if [t.text for t in tokens[i:i+5]] == ['Component', '.', 'onCompleted', ':', '{']]
    # Page loader completion handlers are inside the shadow container: choose the outer/native one.
    a, b = shadow(M, result)
    completed = [i for i in completed if not a <= tokens[i].start < b]
    M.require(len(completed) == 1, 'Unknown Settings completion callback.')
    insertions.append((tokens[pairs[completed[0]+4]].start, COMPLETE_BLOCK))
    for position, body in sorted(insertions, reverse=True): result = result[:position] + body + result[position:]
    result, import_line = inject_import(result, url)
    # Strip our precisely bounded additions: every original byte outside the visual container survives.
    restored = result.replace(ROOT_BLOCK, '', 1).replace(SWITCH_BLOCK, '', 1).replace(COMPLETE_BLOCK, '', 1).replace(import_line, '', 1)
    a, b = shadow(M, restored)
    M.require(restored[:a] + restored[b:] == original_outside, 'Native Settings callback preservation failed.')
    scan(M, result)
    return result


def transform_sidebar(M, source, url):
    M.require('voidOptimizer' not in source and 'VOID REFERENCE UI V3' not in source,
              'A previous Optimizer sidebar is installed without a matching state. Restore its old sidebar before upgrading.')
    tokens, pairs = scan(M, source)
    for text in ('PlrSidebarElement', 'sidebarSettingClicked', 'fResetSidebar'):
        M.require(any(token.text == text for token in tokens), 'Unknown sidebar contract: ' + text)
    def position(pattern, closing=False):
        hits = [i for i in range(len(tokens)-len(pattern)+1) if [t.text for t in tokens[i:i+len(pattern)]] == pattern]
        M.require(len(hits) == 1, 'Unknown/ambiguous sidebar field: ' + pattern[-1])
        index=hits[0]+len(pattern)-1
        return tokens[pairs[index]].start if closing else tokens[index].end
    sidebar_block = SIDEBAR_BLOCK.replace('SIDEBAR_SKIN_URL', json.dumps(url + 'SidebarSkin.qml'))
    inserts = [(position(['id', ':', 'iSidebar']), sidebar_block),
               (position(['property','list','<','QtObject','>','pAllSidebarItems',':','['],closing=True), SIDEBAR_ITEM)]
    result = source
    for at, text in sorted(inserts, reverse=True): result = result[:at] + text + result[at:]
    result, import_line = inject_import(result, url)
    M.require(result.replace(import_line, '', 1).replace(sidebar_block, '', 1).replace(SIDEBAR_ITEM, '', 1) == source,
              'Native sidebar byte preservation failed.')
    # Visual tags only: keep each original asset binding and input handler intact.
    tokens, pairs = scan(M, result)
    tags = []
    aliases = {'iSettingsBtn':'settings','iBackBtn':'back','iHomeBtn':'home','iRecentBtn':'recent','iKebabMenuBtn':'kebab'}
    for i in range(len(tokens)-1):
        if tokens[i].text != 'UiImageButton' or tokens[i+1].text != '{': continue
        opening=i+1; end=pairs[opening]
        words=''.join(t.text for t in tokens[opening+1:end])
        expression='""'
        if 'model.modelData.pAsset' in words: expression='model.modelData.pElementId'
        elif 'modelData.pAsset' in words: expression='modelData.pElementId'
        else:
            j=opening+1
            while j<end:
                if tokens[j].text in ('{','[','(') and j in pairs: j=pairs[j]+1;continue
                if [t.text for t in tokens[j:j+2]]==['id',':']:
                    expression=json.dumps(aliases.get(tokens[j+2].text,''));break
                j+=1
        tags.append((tokens[opening].end,'\nproperty string pVoidElementId: '+expression+'\n'))
    for at,text in sorted(tags,reverse=True): result=result[:at]+text+result[at:]
    scan(M, result)
    return result

"""Reviewed, visual-only edits of real native Settings pages (src-code/some).
Never install page doubles or change model values, signal bodies or backend calls.
"""

import json

PAGE_MARKER = '// VOID NATIVE SETTINGS V4 — layout only; native callbacks retained\n'
PAGE_FIELDS = {'width','height','spacing','font','color','linkColor','text','source',
               'Layout.preferredWidth','Layout.preferredHeight','Layout.minimumWidth',
               'anchors.margins','anchors.leftMargin','anchors.rightMargin','anchors.topMargin','anchors.bottomMargin'}


def page_fields(M, source):
    tokens=M.lex(source);pairs,context,_=M.structure(tokens);fields=[]
    for i,t in enumerate(tokens):
        if t.text!=':' or not context.get(i) or i<1:continue
        start=i-1
        while start>=2 and tokens[start-1].text=='.':start-=2
        name=''.join(token.text for token in tokens[start:i])
        if name not in PAGE_FIELDS:continue
        end=M.expression_end(tokens,i+1,pairs)
        if end<=i+1:continue
        fields.append((name,tokens[i+1].start,tokens[end-1].end,source[tokens[i+1].start:tokens[end-1].end]))
    return tokens,pairs,fields


def page_contract(M, source):
    # Permit reviewed visual palette/typography/label revisions only. Models,
    # validators, enable/visibility predicates, functions and handlers stay in the signature.
    _,_,fields=page_fields(M,source)
    for name,a,b,value in sorted(fields,key=lambda r:r[1],reverse=True):source=source[:a]+'"VOID_VISUAL"'+source[b:]
    return [(token.kind,token.text) for token in M.lex(source)]


def transform_native_page(M, source, baseline, name):
    M.require('VOID NATIVE SETTINGS V4' not in source,'Tracked native page requires matching state: '+name)
    baselines=baseline if isinstance(baseline,(list,tuple)) else [baseline]
    M.require(any(page_contract(M,source)==page_contract(M,reviewed) for reviewed in baselines),
              'Native Settings page logic/hierarchy differs from reviewed src-code/some: '+name+'. Run DIAGNOSE-UI; do not force.')
    tokens,pairs,fields=page_fields(M,source)
    root=next(i for i in range(len(tokens)-1) if tokens[i].text=='Item' and tokens[i+1].text=='{')+1
    end=pairs[root];j=root+1;root_id=None
    while j<end:
        if [t.text for t in tokens[j:j+2]]==['id',':']:root_id=tokens[j+2].text;break
        if tokens[j].text in ('{','[','(') and j in pairs:j=pairs[j]+1
        else:j+=1
    insert=PAGE_MARKER+('id: voidNativeSettingsPage\n' if root_id is None else '')
    root_id=root_id or 'voidNativeSettingsPage'
    edits=[(tokens[root].end,tokens[root].end,'\n'+insert)]
    palette=json.loads(payload()['theme.json'])['palette']
    colors={'primary10':palette['text'],'primary20':palette['muted'],'primary30':palette['muted'],
            'primary60':palette['border'],'primary70':palette['surface'],'primary80':palette['background'],
            'seperator':palette['raised'],'separator':palette['raised'],'accentNormal':palette['accent']}
    fonts={'bodyLarge':12,'bodyMedium':12,'bodySmall':10,'titleSmallest':12,'titleSmall':16}
    for prop,a,b,value in fields:
        replacement=value
        if prop=='width' and value.strip() in ('520','548','560'):
            replacement='Math.min(460, Math.max(0, '+root_id+'.width))'
        elif prop=='Layout.preferredWidth' and value.strip()=='200':replacement='174'
        elif prop=='Layout.preferredHeight' and value.strip()=='36':replacement='29'
        elif prop=='spacing' and value.strip()=='16':replacement='12'
        elif prop=='spacing' and value.strip()=='24':replacement='16'
        elif prop=='text' and value.strip()=='qsTranslate("QObject", "RAM allocation")':replacement='qsTranslate("QObject", "Memory allocation")'
        elif prop=='font':
            for key,size in fonts.items():
                if value.strip()=='UiTheme.fonts.'+key:replacement='Qt.font({family:"Segoe UI",pixelSize:'+str(size)+'})'
        elif prop in ('color','linkColor'):
            # Replace only theme color values inside a visual binding, not arbitrary strings/JS.
            vt=M.lex(value)
            for k in range(len(vt)-4,-1,-1):
                if k+4>=len(vt):continue
                if [t.text for t in vt[k:k+4]]==['UiTheme','.','colors','.'] and vt[k+4].text in colors:
                    replacement=replacement[:vt[k].start]+json.dumps(colors[vt[k+4].text])+replacement[vt[k+4].end:]
        if replacement!=value:edits.append((a,b,replacement))
    result=source
    for a,b,value in sorted(edits,reverse=True):result=result[:a]+value+result[b:]
    # Inverse every visual edit in reverse-offset order to prove original bytes survive.
    offset=0;inverse=[]
    for a,b,value in sorted(edits):
        inverse.append((a+offset,a+offset+len(value),source[a:b]));offset+=len(value)-(b-a)
    restored=result
    for a,b,value in reversed(inverse):restored=restored[:a]+value+restored[b:]
    M.require(restored==source,'Native page byte preservation failed: '+name)
    M.structure(M.lex(result))
    return result


def polish_native_density(m,source):
    # Upgrade existing tracked V4/V5 visual fields too, not only fresh installs.
    # Larger text + usable page width; compact gaps, no model/callback changes.
    tokens,pairs,fields=page_fields(m,source)
    edits=[]
    for prop,a,b,value in fields:
        replacement=value
        if prop=='width' and value.strip().startswith('Math.min(460, Math.max(0, '):
            replacement=value.replace('Math.min(460,','Math.min(660,',1)
        elif prop=='Layout.preferredWidth' and value.strip()=='174':replacement='200'
        elif prop=='Layout.preferredHeight' and value.strip()=='29':replacement='32'
        elif prop=='font' and 'Qt.font' in value and 'Segoe UI' in value:
            replacement=re.sub(r'pixelSize:\s*(10|11|12)\b',lambda hit:'pixelSize:'+('13' if hit[1]=='10' else '14'),value)
        if value!=replacement:edits.append((a,b,replacement))
    result=source
    for a,b,value in sorted(edits,reverse=True):result=result[:a]+value+result[b:]
    m.require(page_contract(m,result)==page_contract(m,source),'Density edit changed native callbacks/models.')
    return result

"""Opt-in migration of the exact mixed installation diagnosed on src-code/new.
This is NOT a state reset, generic adopt mode, cache bypass or unknown-source repair.
The pinned report's whole player/state digests, exact QML and all seven V3 assets
must agree. Ordinary installs retain their original refusal behaviour.
"""

LEGACY_MIGRATION_PROFILE = 'mixed-new-e46be7a-v1'
EDITION4_MIGRATION_PROFILE = 'mixed-new-ee557954-edition4-v1'
REVIEWED_MIGRATION_PROFILES = (LEGACY_MIGRATION_PROFILE, EDITION4_MIGRATION_PROFILE)


def reviewed_v3_state(m, e, packed, root, url):
    old=previous_ui(packed)
    sidebar=packed['baseline/PlrSidebar.qml']
    settings=packed['baseline/UiSettingsWindow.qml']
    def encoded(original,text):
        return (('\ufeff' if original.startswith(b'\xef\xbb\xbf') else '')+text).encode('utf-8')
    expected_core={
        'PlrSidebar.qml':encoded(sidebar,old.transform_sidebar(m,sidebar.decode('utf-8-sig'),url)),
        'UiSettingsWindow.qml':encoded(settings,old.transform_settings(m,settings.decode('utf-8-sig'),settings.decode('utf-8-sig'),url))}
    assets={name[len('migration/v3-assets/'):]:value for name,value in packed.items() if name.startswith('migration/v3-assets/')}
    return {'format':1,'installation':str(root),'assets_url':url,
            'assets':{'Assets/VOIDReferenceUI/'+name:e.sha(value) for name,value in sorted(assets.items())},
            'resources':{name:{'sha256':e.sha(value)} for name,value in expected_core.items()}}


def reviewed_legacy_migration(m,e,packed,root,url,state,state_before,current,player_body):
    edition4=json.loads(packed['migration/edition4/REPORT.json'])
    if e.sha(player_body)==edition4['player_sha256']:
        return reviewed_edition4_migration(m,e,packed,root,url,state,state_before,current,player_body)
    evidence=json.loads(packed['migration/REPORT.json'].decode('utf-8'))
    prefix='Reviewed mixed-UI migration refused: '
    e.need(len(player_body)==evidence['player_bytes'] and e.sha(player_body)==evidence['player_sha256'],
           prefix+'HD-Player.exe does not match the diagnosed player. No generic repair is allowed.')
    e.need(state_before is not None and e.sha(state_before)==evidence['ui_state']['file_sha256'],
           prefix+'state file differs from the diagnosed V3 record. No state is discarded.')
    expected_state=reviewed_v3_state(m,e,packed,root,url)
    e.need(state==expected_state,prefix+'state is not the exact reproducible V3 state for this installation.')
    e.need(len(expected_state['assets'])==7,prefix+'incomplete reviewed V3 asset profile.')
    for name in CORE_NAMES:
        expected=packed['migration/installed/'+name]
        e.need(e.sha(expected)==evidence['resources'][name]['sha256'],prefix+'bundled diagnostic source checksum failed: '+name)
        e.need(current.get(name)==expected,prefix+'installed resource is not the reviewed legacy source: '+name)
    for name,expected_hash in expected_state['assets'].items():
        path=e.safe_target(root,name)
        e.need(path.is_file() and path.stat().st_size<=2*1024*1024,prefix+'missing/oversized V3 asset: '+name)
        value=path.read_bytes();reviewed=packed['migration/v3-assets/'+Path(name).name]
        e.need(e.sha(value)==expected_hash and value==reviewed,prefix+'V3 asset changed: '+name)
    # Remove ONLY the two proven additive legacy V1 blocks, not native callbacks.
    sidebar=current['PlrSidebar.qml']
    for key in ('migration/v1-root-insert.txt','migration/v1-item-insert.txt'):
        block=packed[key]
        e.need(sidebar.count(block)==1,prefix+'legacy insertion is missing/ambiguous.')
        sidebar=sidebar.replace(block,b'',1)
    e.need(sidebar==packed['baseline/PlrSidebar.qml'],prefix+'legacy sidebar inverse did not reproduce the reviewed native baseline.')
    e.need(current['UiSettingsWindow.qml']==packed['baseline/UiSettingsWindow.qml'],prefix+'legacy Settings window differs from the native baseline.')
    return {'PlrSidebar.qml':sidebar,'UiSettingsWindow.qml':current['UiSettingsWindow.qml']}, {
        'profile':LEGACY_MIGRATION_PROFILE,'already_migrated':False,
        'diagnostic_commit':'e46be7a392b458659146d1da89acb08af43c934e',
        'before_player_sha256':e.sha(player_body),'before_state_sha256':e.sha(state_before),
        'all_seven_v3_assets_verified':True,
        'note':'Explicit migration of the exact reviewed mixed state. Old V1 route is removed; native callbacks preserved. Undo returns to the ORIGINAL MIXED state, not healthy V3.'}


def reviewed_edition4_state(packed,root,url):
    report=json.loads(packed['migration/edition4/REPORT.json'])['ui_state']
    return {'format':1,'edition':4,'installation':str(root),'assets_url':url,
            'migration_profile':LEGACY_MIGRATION_PROFILE,
            'assets':{r['name']:r['expected_sha256'] for r in report['assets'] if r['expected_sha256'] is not None},
            'resources':{r['name']:{'sha256':r['expected_sha256'],'container':'HD-Player.exe'} for r in report['resources']}}


def reviewed_edition4_migration(m,e,packed,root,url,state,state_before,current,player_body):
    """Repair only the separately reviewed edition-4 Settings reversion.
    Player AND raw-state digests are mandatory; all assets/resources are checked.
    The old sidebar and pages flow through normal reviewed V4 upgrade checks.
    """
    report=json.loads(packed['migration/edition4/REPORT.json'])
    prefix='Reviewed edition-4 migration refused: '
    e.need(len(player_body)==report['player_bytes'] and e.sha(player_body)==report['player_sha256'],prefix+'player differs from diagnosed snapshot.')
    e.need(state_before is not None and e.sha(state_before)==report['ui_state']['file_sha256'],prefix+'state differs from diagnosed snapshot; no state is discarded.')
    e.need(state==reviewed_edition4_state(packed,root,url),prefix+'state is not the exact reproducible edition-4 record.')
    evidence=report['ui_state']
    e.need(state.get('edition')==4 and not state.get('full_emulator_ui') and state.get('assets_url')==url,prefix+'wrong edition or asset location.')
    expected_resources={row['name']:row for row in evidence['resources']}
    e.need(set(state.get('resources',{}))==set(expected_resources),prefix+'tracked resource set differs.')
    for name,row in expected_resources.items():
        known=state['resources'][name]
        e.need(known.get('sha256')==row['expected_sha256'] and known.get('container')=='HD-Player.exe',prefix+'tracked source differs: '+name)
        expected=packed['migration/edition4/'+(name if name in CORE_NAMES else 'pages/'+name)]
        e.need(current.get(name)==expected and e.sha(expected)==row['observed'][0]['sha256'],prefix+'installed source differs: '+name)
    expected_assets={row['name']:row['expected_sha256'] for row in evidence['assets'] if row['expected_sha256'] is not None}
    e.need(state.get('assets')==expected_assets and len(expected_assets)==7,prefix+'asset record differs.')
    for name,digest in expected_assets.items():
        target=e.safe_target(root,name)
        e.need(target.is_file() and target.stat().st_size<=2*1024*1024 and e.sha(target.read_bytes())==digest,prefix+'asset changed: '+name)
    # The single accepted mismatch must be the unchanged pinned native Settings.
    native=packed['baseline/UiSettingsWindow.qml']
    e.need(current['UiSettingsWindow.qml']==native,prefix+'Settings is not the reviewed native baseline.')
    return {'UiSettingsWindow.qml':native},{
        'profile':EDITION4_MIGRATION_PROFILE,'already_migrated':False,
        'diagnostic_commit':'ee557954ee9e1a251f20fe667d2bbcc1f711d26b',
        'before_player_sha256':e.sha(player_body),'before_state_sha256':e.sha(state_before),
        'all_seven_v3_assets_verified':True,
        'note':'Exact edition-4 Settings reversion repaired; all other tracked sources verified. Undo restores the ORIGINAL MIXED snapshot.'}

"""Mapped native palette extension, sharing Reference UI state/backup/cache checks.
Never theme boot/auth/global palette/framework resources or JS business logic.
All protected/unsupported resources are listed, not claimed as redesigned.
"""

def previous_ui(packed):
    scope={}
    exec(compile(packed['previous/transform.py'],'reviewed-v4-transform.py','exec'),scope)
    return types.SimpleNamespace(**scope)


def upgrade_core(m,e,packed,name,source,url):
    old=previous_ui(packed)
    base=packed['baseline/'+name]
    native=base.decode('utf-8-sig')
    expected=old.transform_settings(m,native,native,url) if name=='UiSettingsWindow.qml' else old.transform_sidebar(m,native,url)
    expected=(('\ufeff' if base.startswith(b'\xef\xbb\xbf') else '')+expected).encode('utf-8')
    e.need(source==expected,'Tracked old core source is not the exact reviewed V3/V4 bridge: '+name+'. Keep state/backups and run DIAGNOSE-UI; no forced replacement.')
    updated=transform_settings(m,native,native,url) if name=='UiSettingsWindow.qml' else transform_sidebar(m,native,url)
    return (('\ufeff' if base.startswith(b'\xef\xbb\xbf') else '')+updated).encode('utf-8')


def topbar_adapter(m,source,url):
    marker='// VOID FULL UI V5 TOPBAR'
    if marker in source:return source
    tokens,pairs=scan(m,source)
    roots=[i for i in range(len(tokens)-1) if tokens[i].text=='Rectangle' and tokens[i+1].text=='{']
    m.require(roots and any(t.text=='UiImageButton' for t in tokens),'Unknown topbar visual contract; run DIAGNOSE-UI.')
    opening=roots[0]+1
    # Parent is the actual native topbar root; no new mouse areas or actions.
    block='\n'+marker+'\nLoader { objectName:"voidReferenceTopbarLoader"; source:'+json.dumps(url+'TopbarSkin.qml')+'; onLoaded:item.host=parent }\n'
    result=source[:tokens[opening].end]+block+source[tokens[opening].end:]
    m.require(result.replace(block,'',1)==source,'Topbar byte preservation failed.')
    return result


def full_ui_inventory(m,e,images,root,current,owners):
    all_sources={};candidates={};rows_by_name={};coverage=[];total=0
    for path,(body,rows) in images.items():
        for row in rows:
            if not row.name.lower().endswith(('.qml','.js','.svg')):continue
            if m.framework_path(row.path):continue
            value=e.unpack_record(body,row.entry,row.flags)
            e.need(len(value)<=e.MAX_SOURCE,'Oversized native UI source: '+row.path)
            total+=len(value)
            e.need(total<=m.MAX_TOTAL and len(all_sources)<m.MAX_FILES,'Full UI inventory exceeds safety bounds.')
            key=path.relative_to(root).as_posix()+'/'+row.path
            # The manager's framework/boot names are matched using native paths,
            # not the container prefix. Cross-container dependency names still join.
            all_sources[key]=value
            rows_by_name.setdefault(row.name,[]).append((path,row,value,key))
    text={key:value for key,value in all_sources.items() if not key.lower().endswith('.svg')}
    protected=m.protected_paths(text)
    protected_svg=m.protected_control_svgs(all_sources,protected)
    config=m.validate_theme(json.loads(payload()['theme.json']))
    for name,entries in sorted(rows_by_name.items()):
        if name in RESOURCE_NAMES:continue
        path,row,value,key=entries[0]
        reason=protected.get(key)
        # Preserve authentication/legal/account screens even if they are not boot dependencies.
        if any(word in name.lower() for word in ('login','auth','signin','account','license','consent','payment')):reason='auth/account/legal UI preserved'
        if name.lower().endswith('.js'):reason=reason or 'JavaScript logic is inventory-only'
        if name.lower().endswith('.svg'):reason=reason or m.control_svg_reason(key,config,protected_svg)
        if reason:
            coverage.append({'name':name,'container':path.relative_to(root).as_posix(),'status':'protected','reason':reason});continue
        e.need(len({(p,r.path) for p,r,_,_ in entries})==1 and len({v for _,_,v,_ in entries})==1,'Ambiguous full UI resource: '+name)
        if name in current:
            e.need(owners[name]==path and current[name]==value,'Tracked full UI source moved/changed: '+name)
        candidates[name]=(value,key)
        current[name]=value;owners[name]=path
    return candidates,config,coverage


def style_full_source(m,name,source,path,config,url):
    if name.lower().endswith('.svg'):
        result,edits,unsupported=m.style_svg(source,config,path)
        return result,edits,unsupported
    text=source.decode('utf-8-sig')
    result,edits,unsupported=m.style(text,config,path)
    if name=='PlrTopbar.qml':result=topbar_adapter(m,result,url)
    result=native_surface_adapter(m,name,result,url)
    return (('\ufeff' if source.startswith(b'\xef\xbb\xbf') else '')+result).encode('utf-8'),edits,unsupported


def hide_boot_caption(e,packed,source):
    original=packed['boot-text/PlrBootProgressBar.qml']
    caption=b'text: qsTranslate("QObject", "Loading...")'
    e.need(original.count(caption)==1 and b'id: iBootLoadingText' in original,'Invalid reviewed boot caption baseline.')
    hidden=original.replace(caption,b'text: "" // VOID BOOT CAPTION ONLY',1)
    e.need(source in (original,hidden),'Boot caption source differs from reviewed snapshot. No boot callbacks are adopted or rewritten; keep current boot and share diagnostic source.')
    return hidden


def native_surface_adapter(m,name,source,url):
    # Passive control visuals only: no MouseArea, key bindings, timers, actions,
    # scheme models, drag targets or persistence callbacks are replaced.
    if name not in ('PlrSidebar.qml','UiDialog.qml','KmmEditorWindow.qml'):
        return source
    marker='// VOID NATIVE SURFACE CONTROLS V5.1'
    if marker in source:return source
    tokens,pairs=scan(m,source)
    opening=next((i for i,t in enumerate(tokens) if t.text=='{'),None)
    m.require(opening is not None,'Missing native surface root: '+name)
    block='\n'+marker+'\nLoader { objectName:"voidSurfaceControlsLoader"; visible:false; source:'+json.dumps(url+'NativeControlStyle.qml')+'; onLoaded:item.pages=parent }\n'
    result=source[:tokens[opening].end]+block+source[tokens[opening].end:]
    m.require(result.replace(block,'',1)==source,'Native surface callback preservation failed: '+name)
    scan(m,result)
    return result



def payload():
    body = base64.b85decode(ASSETS_B85)
    if hashlib.sha256(body).hexdigest() != ASSETS_SHA256: raise RuntimeError('UI assets checksum failed.')
    with zipfile.ZipFile(io.BytesIO(body)) as archive:
        return {name: archive.read(name) for name in archive.namelist()}


def selected_sources(e, body, rows, names=CORE_NAMES):
    result = {}
    for name in names:
        matches = [r for r in rows if r.name == name]
        e.need(matches and len({r.path for r in matches}) == 1, 'Missing/ambiguous native resource: ' + name)
        sources = {e.unpack_record(body, r.entry, r.flags) for r in matches}
        e.need(len(sources) == 1, 'Conflicting locale sources for ' + name)
        source = sources.pop(); source.decode('utf-8-sig')
        result[name] = source
    return result


def source_inventory(e, body, packed):
    # Keep the audited canonical-tree fallback for builds without a discovered
    # registration. Restrict targets to names actually present in this image;
    # unrelated per-DLL names must not force a second/stale pool interpretation.
    bundle,_=e.load_bundle(base64.b85decode(e.PAYLOAD_B85),e.PAYLOAD_SHA256,e.ACCEPTED)
    probes={name:value for name,value in bundle.items() if name in RESOURCE_NAMES}
    for name in RESOURCE_NAMES:
        key=('baseline/'+name) if name in CORE_NAMES else ('baseline/pages/'+name)
        if key in packed:probes[name]=packed[key]
    accepted={name:list(e.ACCEPTED.get(name,[])) for name in probes}
    for name,value in probes.items():accepted[name].append(e.source_identity(value,name))
    wanted={name:value for name,value in probes.items() if name.encode('utf-16-be') in body}
    return e.resources_in(body,accepted,wanted)[1]


def resource_state_error(e,name,known,source,reason):
    expected=known.get('sha256') if isinstance(known,dict) else None
    if not isinstance(expected,str) or not re.fullmatch(r'[0-9a-f]{64}',expected):expected='missing/invalid'
    return (reason+': '+name+'\nExpected tracked SHA256: '+expected+
            '\nActual resource SHA256: '+e.sha(source)+
            '\nNo files changed. Run DIAGNOSE-UI.cmd and share VOID-UI-Diagnostics.zip; do not delete state/backups or force an overwrite.')


def diagnostic_state(e,m,root,observed):
    result={'exists':False,'resources':[],'assets':[]}
    try:
        path=e.safe_target(root,UI_STATE)
        if not path.exists():return result
        result['exists']=True
        e.need(path.stat().st_size<=2*1024*1024,'Oversized reference UI state.')
        body=path.read_bytes();result['file_sha256']=e.sha(body)
        state=m.read_json(body)
        e.need(isinstance(state,dict),'Reference UI state is not an object.')
        result['format']=state.get('format') if type(state.get('format')) is int else None
        result['edition']=state.get('edition') if type(state.get('edition')) is int else None
        result['installation_matches']=state.get('installation')==str(root)
        result['assets_url_matches']=state.get('assets_url')==(root/'Assets/VOIDReferenceUI').as_uri()+'/'
        resources=state.get('resources',{});assets=state.get('assets',{})
        e.need(isinstance(resources,dict) and isinstance(assets,dict),'Invalid state resource/asset tables.')
        extra=sorted(name for name in resources if state.get('full_emulator_ui') and isinstance(name,str) and re.fullmatch(r'[A-Za-z0-9_.-]{1,120}\.(?:qml|svg)',name) and name not in RESOURCE_NAMES)
        e.need(len(extra)<=4096,'Oversized full UI state resource table.')
        result['full_emulator_ui']=state.get('full_emulator_ui') is True
        result['unexpected_resource_count']=len(set(resources).difference(RESOURCE_NAMES).difference(extra))
        for name in (*RESOURCE_NAMES,*extra):
            known=resources.get(name);expected=known.get('sha256') if isinstance(known,dict) else None
            valid=isinstance(expected,str) and bool(re.fullmatch(r'[0-9a-f]{64}',expected))
            actual=observed.get(name,[])
            result['resources'].append({'name':name,'tracked':name in resources,
                'expected_sha256':expected if valid else None,'observed':actual,
                'digest_matches':bool(valid and actual and all(row['sha256']==expected for row in actual))})
        # Only known asset paths; never follow arbitrary paths supplied by a state file.
        for name in sorted(key for key in payload() if key.startswith('Assets/')):
            expected=assets.get(name)
            valid=isinstance(expected,str) and bool(re.fullmatch(r'[0-9a-f]{64}',expected))
            entry={'name':name,'expected_sha256':expected if valid else None}
            try:
                target=e.safe_target(root,name)
                e.need(not target.exists() or (target.is_file() and target.stat().st_size<=2*1024*1024),'Oversized/non-file UI asset.')
                value=target.read_bytes() if target.exists() else None
                entry['actual_sha256']=e.digest(value)
                entry['digest_matches']=bool(valid and entry['actual_sha256']==expected)
            except (e.Refusal,OSError) as error:entry['error']=str(error)
            result['assets'].append(entry)
    except (e.Refusal,RuntimeError,ValueError,UnicodeError,OSError) as error:
        result['error']=str(error)
    return result


def plan_install(root, migrate_reviewed_legacy=False, full_emulator_ui=False, hide_boot_loading_text=False):
    m=manager();e=m.engine();root=e.canonical_root(root)
    e.need(not e.safe_target(root,m.STATE_NAME).exists(),'A Theme Manager baseline is active. Undo its theme transaction first; no silent baseline reset.')
    packed=payload();player=e.safe_target(root,'HD-Player.exe')
    e.need(player.is_file() and player.stat().st_size<=e.MAX_FILE,'Select the folder containing a bounded HD-Player.exe.')
    before=player.stat();body=player.read_bytes();after=player.stat()
    e.need((before.st_size,before.st_mtime_ns)==(after.st_size,after.st_mtime_ns),'Player changed while reading.')
    rows=source_inventory(e,body,packed)
    current=selected_sources(e,body,rows)
    owners={name:player for name in current};images={player:(body,rows)}
    state_path=e.safe_target(root,UI_STATE)
    state_before=state_path.read_bytes() if state_path.exists() else None
    state=m.read_json(state_before) if state_before else {}
    e.need(not state or (state.get('format')==1 and state.get('installation')==str(root) and isinstance(state.get('resources'),dict) and isinstance(state.get('assets'),dict)),'Invalid/wrong-install UI state.')
    full_emulator_ui=full_emulator_ui or bool(state.get('full_emulator_ui'))
    hide_boot_loading_text=hide_boot_loading_text or bool(state.get('hide_boot_loading_text'))
    native_names=set(RESOURCE_NAMES)|set(state.get('resources',{}))
    candidates=list(e.candidate_files(root))
    # Find the reviewed page sources in their REAL owning PE container. Never
    # shadow them with local page doubles or assume every page lives in Player.
    for path in candidates:
        if path.suffix.lower()=='.exe' and path!=player:continue
        e.safe_target(root,path.relative_to(root))
        e.need(path.stat().st_size<=e.MAX_FILE,'Container exceeds safety limit: '+path.name)
        data=body if path==player else path.read_bytes()
        if path!=player and not any(name.encode('utf-16-be') in data for name in native_names) and not (full_emulator_ui and '.qml'.encode('utf-16-be') in data):continue
        mapped=rows if path==player else source_inventory(e,data,packed)
        names={r.name for r in mapped if r.name in native_names}
        if path!=player:
            e.need(not names.intersection(CORE_NAMES),'Ambiguous Settings/sidebar source in another container: '+path.name)
        for name in sorted(names.difference(CORE_NAMES)):
            e.need(name not in owners,'Ambiguous native Settings page container: '+name)
            source=selected_sources(e,data,mapped,(name,))[name]
            current[name]=source;owners[name]=path
        if names or full_emulator_ui:images[path]=(data,mapped)
    e.need('UiPerformanceSetting.qml' in current,'Actual UiPerformanceSetting.qml source is missing. This edition will not install another fake Performance form; run DIAGNOSE-UI.')
    full_candidates={};full_config=None;coverage=[]
    if full_emulator_ui:full_candidates,full_config,coverage=full_ui_inventory(m,e,images,root,current,owners)
    if hide_boot_loading_text:
        # A separate explicit action, never a blanket exception to boot protection.
        boot='PlrBootProgressBar.qml'
        matches=[]
        for path in candidates:
            if path.suffix.lower()=='.exe' and path!=player:continue
            if path not in images:
                e.safe_target(root,path.relative_to(root));e.need(path.stat().st_size<=e.MAX_FILE,'Oversized boot container')
                data=path.read_bytes()
                if boot.encode('utf-16-be') not in data:continue
                images[path]=(data,source_inventory(e,data,packed))
            data,mapped=images[path]
            if any(r.name==boot for r in mapped):matches.append((path,data,mapped))
        e.need(len(matches)==1,'Boot caption resource missing/ambiguous; nothing changed.')
        path,data,mapped=matches[0]
        current[boot]=selected_sources(e,data,mapped,(boot,))[boot];owners[boot]=path
        hide_boot_caption(e,packed,current[boot])
    e.need(not set(state.get('resources',{})).difference(current),'Tracked native page disappeared; restore before upgrading.')
    url=(root/'Assets/VOIDReferenceUI').as_uri()+'/'
    migration_sources={};migration_info=None
    if migrate_reviewed_legacy:
        if state.get('edition')==5 and state.get('migration_profile') in REVIEWED_MIGRATION_PROFILES:
            migration_info={'profile':state['migration_profile'],'already_migrated':True}
        else:
            migration_sources,migration_info=reviewed_legacy_migration(m,e,packed,root,url,state,state_before,current,body)
    desired={}
    for name,source in current.items():
        text=source.decode('utf-8-sig');known=state.get('resources',{}).get(name,{})
        if hide_boot_loading_text and name=='PlrBootProgressBar.qml':
            if known:
                e.need(known.get('sha256')==e.sha(source) and known.get('container')==owners[name].relative_to(root).as_posix(),'Tracked boot caption resource changed or moved; no bypass.')
            desired[name]=hide_boot_caption(e,packed,source)
        elif name not in RESOURCE_NAMES:
            if known:
                e.need(known.get('sha256')==e.sha(source),resource_state_error(e,name,known,source,'Tracked full UI resource changed'))
                e.need(known.get('container')==owners[name].relative_to(root).as_posix(),'Tracked full UI resource moved: '+name)
            if name in full_candidates:
                value,path=full_candidates[name]
                desired[name],edits,unsupported=style_full_source(m,name,value,path,full_config,url)
                coverage.append({'name':name,'container':owners[name].relative_to(root).as_posix(),'status':'changed' if desired[name]!=source else 'unchanged','edits':len(edits),'unsupported_bindings':unsupported})
            else:desired[name]=source
        elif name in migration_sources:
            # Only the separately confirmed exact mixed profile may replace these
            # stale tracked core resources; ordinary installs still refuse.
            base=migration_sources[name];native=base.decode('utf-8-sig')
            text=transform_settings(m,native,packed['baseline/UiSettingsWindow.qml'].decode('utf-8-sig'),url) if name=='UiSettingsWindow.qml' else transform_sidebar(m,native,url)
            desired[name]=( ('\ufeff' if base.startswith(b'\xef\xbb\xbf') else '')+text).encode('utf-8')
        elif 'VOID REFERENCE UI V3' in text or 'VOID NATIVE SETTINGS V4' in text:
            e.need(known.get('sha256')==e.sha(source) and state.get('assets_url')==url,resource_state_error(e,name,known,source,'Installed reference UI differs from its state'))
            if known.get('container') is not None:e.need(known['container']==owners[name].relative_to(root).as_posix(),'Tracked UI resource moved containers: '+name)
            desired[name]=upgrade_core(m,e,packed,name,source,url) if name in CORE_NAMES and state.get('edition')!=5 else source
        else:
            e.need(not known and (name not in CORE_NAMES or not state),resource_state_error(e,name,known,source,'Tracked reference UI resource disappeared/changed or patch marker missing'))
            if name=='UiSettingsWindow.qml':text=transform_settings(m,text,packed['baseline/UiSettingsWindow.qml'].decode('utf-8-sig'),url)
            elif name=='PlrSidebar.qml':text=transform_sidebar(m,text,url)
            else:
                baselines=[packed['baseline/pages/'+name].decode('utf-8-sig')]
                if 'baseline/variants/'+name in packed:baselines.append(packed['baseline/variants/'+name].decode('utf-8-sig'))
                text=transform_native_page(m,text,baselines,name)
            desired[name]=(('\ufeff' if source.startswith(b'\xef\xbb\xbf') else '')+text).encode('utf-8')
    if full_emulator_ui:
        name='PlrSidebar.qml'
        source=desired[name]
        text=native_surface_adapter(m,name,source.decode('utf-8-sig'),url)
        desired[name]=(('\ufeff' if source.startswith(b'\xef\xbb\xbf') else '')+text).encode('utf-8')
        for name in PAGE_NAMES:
            if name in desired:
                desired[name],_,_=style_full_source(m,name,desired[name],name,full_config,url)
                desired[name]=polish_native_density(m,desired[name].decode('utf-8-sig')).encode('utf-8-sig') if desired[name].startswith(b'\xef\xbb\xbf') else polish_native_density(m,desired[name].decode('utf-8')).encode('utf-8')
    accepted={name:[e.source_identity(source,name)] for name,source in current.items()}
    needed={name:source for name,source in desired.items() if source!=current[name]}
    plan=e.Plan(root)
    report={'format':1,'edition':5,'mode':'native-reference-ui','installation_modified':False,'boot_modified':False,
            'exact_native_page_layout_certified':False,'native_runtime_certified':False,'resources':[],
            'missing_optional_pages':sorted(set(PAGE_NAMES).difference(current)),
            'changed_files':[],'assets_url':url,'page_source_commit':'f76496dff668139f09128d21d98ebdde32d639c0',
            'note':'Actual native page layout/typography is patched, not the fixture. Original configuration/event bodies are retained. Live emulator testing remains required.'}
    report['boot_modified']=hide_boot_loading_text and desired.get('PlrBootProgressBar.qml')!=current.get('PlrBootProgressBar.qml')
    report['boot_caption_hidden']=hide_boot_loading_text
    report['boot_logic_modified']=False
    report['full_emulator_ui']=full_emulator_ui
    report['native_coverage']=coverage
    report['all_emulator_ui_certified']=False
    report['topbar_present']='PlrTopbar.qml' in current
    report['untouched_surfaces']=['boot/loading','auth/account/legal UI','global/shared boot palette','Qt framework','arbitrary raster artwork','C++/Android/game UI','unsupported dynamic paint bindings']
    if migration_info is not None:report['migration']=migration_info
    for name in sorted(current):
        report['resources'].append({'name':name,'container':owners[name].relative_to(root).as_posix(),'before_sha256':e.sha(current[name]),'after_sha256':e.sha(desired[name]),'changed':name in needed})
    if needed:
        for path in candidates:
            if path.suffix.lower()=='.exe' and path!=player:continue
            e.safe_target(root,path.relative_to(root));e.need(path.stat().st_size<=e.MAX_FILE,'Container exceeds safety limit: '+path.name)
            data,mapped=images[path] if path in images else (path.read_bytes(),None)
            if mapped is None:
                if e.CACHE_MAGIC not in data and not any(name.encode('utf-16-be') in data for name in needed):continue
                mapped=e.resources_in(data,accepted,needed)[1]
            if e.verified_framework(data,mapped,needed):continue
            e.need(all(owners.get(r.name,path)==path for r in mapped if r.name in needed),'UI source container changed during preflight.')
            try:patched=e.patch_image(data,mapped,needed,accepted)
            except (e.Refusal,UnicodeError,zlib.error) as error:raise RuntimeError(path.name+': '+str(error)) from error
            local_names=tuple(name for name in current if owners[name]==path)
            if local_names:
                _,checked=e.resources_in(patched,accepted,{name:desired[name] for name in local_names})
                read_back=selected_sources(e,patched,checked,local_names)
                e.need(read_back=={name:desired[name] for name in local_names},'Preflight embedded-resource read-back mismatch: '+path.name)
            if data!=patched:plan.changes.append(e.Change(path.relative_to(root).as_posix(),data,patched))
    asset_hashes={}
    for name,value in sorted(packed.items()):
        if not name.startswith('Assets/'):continue
        target=e.safe_target(root,name);previous=target.read_bytes() if target.exists() else None
        if state:e.need(state.get('assets',{}).get(name)==e.digest(previous),'Installed UI asset changed externally: '+name)
        asset_hashes[name]=e.sha(value)
        if previous!=value:plan.changes.append(e.Change(name,previous,value))
    next_state={'format':1,'edition':5,'installation':str(root),'assets_url':url,'assets':asset_hashes,
                'resources':{name:{'sha256':e.sha(value),'container':owners[name].relative_to(root).as_posix()} for name,value in desired.items()}}
    if full_emulator_ui:next_state['full_emulator_ui']=True
    if hide_boot_loading_text:next_state['hide_boot_loading_text']=True
    if migration_info is not None or state.get('migration_profile') in REVIEWED_MIGRATION_PROFILES:
        next_state['migration_profile']=migration_info['profile'] if migration_info is not None else state['migration_profile']
    after_state=(json.dumps(next_state,sort_keys=True,indent=2)+'\n').encode('utf-8')
    if state_before!=after_state:plan.changes.append(e.Change(UI_STATE,state_before,after_state))
    report['changed_files']=[change.relative for change in plan.changes]
    return plan,report


def diagnose_ui(root, destination):
    m=manager();e=m.engine();root=e.canonical_root(root)
    destination=destination.absolute()
    e.need(root != destination.resolve() and root not in destination.resolve().parents, 'Save diagnostic ZIP outside the installation.')
    e.need(destination.resolve()!=m.application_file() and not destination.is_symlink(), 'Diagnostic must not overwrite the app or a link.')
    player=e.safe_target(root,'HD-Player.exe')
    e.need(player.stat().st_size<=e.MAX_FILE,'Oversized player.')
    body=player.read_bytes()
    rows=source_inventory(e,body,payload())
    sources=selected_sources(e,body,rows)
    report={'format':1,'mode':'read-only-native-ui-diagnostic','installation_modified':False,'binary_included':False,
            'player_bytes':len(body),'player_sha256':e.sha(body),
            'resources':{name:{'bytes':len(value),'sha256':e.sha(value)} for name,value in sources.items()}}
    try:
        e.disable_compiled(bytearray(body),rows,sources)
        report['compiled_preflight']='owner checks passed (RAM only; no file write)'
    except (e.Refusal,UnicodeError,zlib.error) as error:
        report['compiled_preflight_error']=str(error)
    members={'Sources/'+name:value for name,value in sources.items()}
    # Explicit diagnostic command only: export bounded SETTINGS QML, never binaries/game data.
    # The earlier screenshot used page doubles; real layout work needs the installed pages.
    report['settings_qml_inventory']=[]
    report['settings_qml_exports']=[]
    report['settings_qml_errors']=[]
    observed={}
    total=0
    for path in e.candidate_files(root):
        if path.suffix.lower()=='.exe' and path != player: continue
        try:
            e.safe_target(root,path.relative_to(root))
            e.need(path.stat().st_size<=e.MAX_FILE,'Diagnostic container too large: '+path.name)
            data=body if path == player else path.read_bytes()
            mapped=rows if path == player else e.resources_in(data,{},{} )[1]
            for row in mapped:
                name=row.name
                if name.lower().endswith(('.qml','.svg')) and not m.framework_path(row.path) and len(observed)<4096:
                    value=e.unpack_record(data,row.entry,row.flags)
                    entry={'container':path.name,'sha256':e.sha(value),'core_marker':b'VOID REFERENCE UI V3' in value,'page_marker':b'VOID NATIVE SETTINGS V4' in value}
                    if entry not in observed.setdefault(name,[]):observed[name].append(entry)
                if not name.lower().endswith('.qml'):continue
                if name!='PlrBootProgressBar.qml' and any(word in name.lower() for word in ('boot','splash','login','auth','promo')):continue
                if name!='PlrBootProgressBar.qml' and not re.search(r'setting|performance|engine|graphic|display|preference|combobox|togglebutton|slider|checkbox|radiobutton|uitheme|uibutton|uitext|topbar',name,re.I):continue
                report['settings_qml_inventory'].append({'container':path.name,'resource':row.path})
                if len(report['settings_qml_exports'])>=256 or total>=8*1024*1024:continue
                value=e.unpack_record(data,row.entry,row.flags)
                if name in RESOURCE_NAMES:
                    entry={'container':path.name,'sha256':e.sha(value),
                           'core_marker':b'VOID REFERENCE UI V3' in value,
                           'page_marker':b'VOID NATIVE SETTINGS V4' in value}
                    if entry not in observed.setdefault(name,[]):observed[name].append(entry)
                if len(value)>512*1024 or total+len(value)>8*1024*1024:continue
                value.decode('utf-8-sig')
                # Hash-based folder avoids traversal and duplicate-locale overwrites.
                safe_name=re.sub(r'[^A-Za-z0-9_.-]','_',name)
                key='NativeSettings/'+e.sha((path.name+row.path).encode('utf-8'))[:16]+'/'+safe_name
                members[key]=value;total+=len(value)
                report['settings_qml_exports'].append({'file':key,'sha256':e.sha(value),'bytes':len(value)})
        except (e.Refusal,RuntimeError,ValueError,UnicodeError,zlib.error,OSError) as error:
            report['settings_qml_errors'].append({'container':path.name,'error':str(error)})
    report['settings_qml_export_limit']='256 files, 8 MiB total, 512 KiB per file; sources only'

    # Sidebar is not a Settings-named resource in the bounded export loop.
    for name,value in sources.items():
        if name not in observed:observed[name]=[{'container':player.name,'sha256':e.sha(value),'core_marker':b'VOID REFERENCE UI V3' in value,'page_marker':b'VOID NATIVE SETTINGS V4' in value}]
    report['ui_state']=diagnostic_state(e,m,root,observed)
    report['diagnostic_revision']=2
    members['REPORT.json']=(json.dumps(report,indent=2)+'\n').encode('utf-8')
    members['MANIFEST-SHA256.txt']=''.join(e.sha(value)+'  '+name+'\n' for name,value in sorted(members.items())).encode('ascii')
    stream=io.BytesIO()
    with zipfile.ZipFile(stream,'w',zipfile.ZIP_DEFLATED) as z:
        for name,value in sorted(members.items()):z.writestr(name,value)
    e.atomic_write(destination,stream.getvalue(),0o600)
    return destination


def latest_backup(root):
    e = manager().engine(); root=e.canonical_root(root); folder = e.safe_target(root,'VOID-UI-Backups')
    candidates = []
    if folder.is_dir():
        for path in folder.iterdir():
            e.safe_target(root, 'VOID-UI-Backups/'+path.name)
            journal = path/'journal.json'
            if not journal.is_file(): continue
            value = json.loads(journal.read_text())
            if value.get('status') in ('applied','applying','ready') and any(row.get('path')==UI_STATE for row in value.get('records',[])):
                candidates.append((journal.stat().st_mtime_ns,path))
    e.need(candidates,'No Reference UI transaction to restore. Old theme/control-pack backups are not chosen.')
    return max(candidates)[1]


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    modes = parser.add_mutually_exclusive_group()
    modes.add_argument('--apply', action='store_true')
    modes.add_argument('--check', action='store_true')
    modes.add_argument('--restore-latest', action='store_true')
    modes.add_argument('--runtime-check', action='store_true')
    modes.add_argument('--diagnose-ui', action='store_true')
    modes.add_argument('--check-reviewed-legacy', action='store_true', help='Read-only validation of the pinned src-code/new mixed installation.')
    modes.add_argument('--migrate-reviewed-legacy', action='store_true', help='Explicit backed-up migration of ONLY the exact reviewed mixed installation.')
    parser.add_argument('--install-dir',type=Path)
    parser.add_argument('--full-emulator-ui',action='store_true',help='Theme mapped eligible native resources in the same guarded transaction; report protected/unsupported UI.')
    parser.add_argument('--hide-boot-loading-text',action='store_true',help='Explicitly hide ONLY the pinned static boot loading caption; native boot logic stays intact.')
    parser.add_argument('--report',type=Path)
    parser.add_argument('--diagnostic-output',type=Path)
    parser.add_argument('--yes',action='store_true')
    parser.add_argument('--pause',action='store_true')
    args = parser.parse_args(argv)
    m = manager(); e = m.engine()
    if args.runtime_check:
        payload(); m.runtime_check(); return 0
    root = e.canonical_root(args.install_dir or e.choose_folder())
    forwarded = list(sys.argv[1:] if argv is None else argv)+['--install-dir',str(root)]
    if args.report: forwarded += ['--report',str(args.report.absolute())]
    if (args.apply or args.restore_latest or args.migrate_reviewed_legacy) and m.elevate_manager(root,forwarded): return 0
    print('VOID FULL UI V5 — Carbon palette / incremental styling / native session tools; boot logic protected')
    print('Installation:',root)
    if args.diagnose_ui:
        destination=args.diagnostic_output or m.application_file().with_name('VOID-UI-Diagnostics.zip')
        print('READ ONLY UI DIAGNOSTIC:',diagnose_ui(root,destination))
        print('Only Settings/sidebar/control QML and metadata exported. No EXE, DLL or upload.'); return 0
    if args.restore_latest:
        e.need(not e.running_players(),'Close player and multi-instance manager before restore.')
        with e.install_lock(root):
            backup = latest_backup(root)
            if not args.yes: e.need(input('Type RESTORE: ').strip()=='RESTORE','Cancelled.')
            e.restore(backup,root)
        print('RESTORED:',backup); return 0
    def prepare():
        plan, report = plan_install(root,migrate_reviewed_legacy=args.check_reviewed_legacy or args.migrate_reviewed_legacy,full_emulator_ui=args.full_emulator_ui,hide_boot_loading_text=args.hide_boot_loading_text)
        if args.report: m.write_report(args.report,report,root,Path(__file__))
        if report.get('migration'):
            print('REVIEWED MIXED-UI MIGRATION:',report['migration']['profile'])
            if report['migration'].get('already_migrated'):
                print('Previously migrated installation: verifying current resource/state/asset hashes.')
            else:
                print('Whole player/state digests, exact legacy sources and V3 asset integrity checked. Undo returns to the pre-repair mixed state.')
        for resource in report['resources']: print('Embedded:',resource['name'],'->',resource['after_sha256'][:16], '(will change)' if resource['changed'] else '(verified installed)')
        if report.get('full_emulator_ui'):
            print('Native palette coverage:',sum(r['status']=='changed' for r in report['native_coverage']),'changed;',sum(r['status']=='protected' for r in report['native_coverage']),'protected. Unsupported bindings are listed in the report; this is not a full-emulator runtime certification.')
            if not report['topbar_present']:print('TOPBAR NOT PRESENT: not patched in this installation.')
        if report.get('missing_optional_pages'):print('Not present in this build (not patched):', ', '.join(report['missing_optional_pages']))
        for change in plan.changes: print('  '+change.relative)
        return plan
    if not (args.apply or args.migrate_reviewed_legacy):
        prepare()
        print('CHECK PASSED — no installation files changed. Run '+('REPAIR-MIXED-UI.cmd for the reviewed migration.' if args.check_reviewed_legacy else 'INSTALL-UI.cmd to actually install.'))
        return 0
    e.need(not e.running_players(),'Close the player and multi-instance manager. No process is killed automatically.')
    with e.install_lock(root):
        e.need(not e.incomplete_backups(root),'An interrupted VOID transaction needs explicit recovery first.')
        plan = prepare()
        if not plan.changes: print('VERIFIED INSTALLED: both embedded resources and all UI assets match this edition.'); return 0
        print('Binary changes invalidate Authenticode signatures. Backup/restore covers every changed file.')
        word='MIGRATE' if args.migrate_reviewed_legacy else 'APPLY'
        if args.migrate_reviewed_legacy:print('This upgrades the exact reviewed mixed UI snapshot to V5 and records the full existing mixed state in the transaction backup. No state is deleted first.')
        if not args.yes:e.need(input('Type '+word+' to '+('repair the reviewed mixed installation: ' if args.migrate_reviewed_legacy else 'install the UI: ')).strip()==word,'Cancelled.')
        e.need(not e.running_players(),'Player opened during preflight; close it and retry.')
        folder = e.commit(plan)
    print('INSTALLED AND READ-BACK VERIFIED. Backup:',folder)
    print('Restart emulator. Settings now uses the reference shell and contains the VOID Optimizer tab.')
    print('Test native Save/discard, icons, controls, sidebar/F9 and boot. Use UNDO-UI.cmd for recovery.')
    return 0


if __name__ == '__main__':
    status = 0
    try: status = main()
    except (RuntimeError,OSError,ValueError,UnicodeError,KeyError,TypeError,zlib.error) as error:
        print('STOPPED:',error); status = 1
    if '--pause' in sys.argv:
        try: input('Press Enter to close...')
        except EOFError: pass
    raise SystemExit(status)
